# Parse test grid G already loaded above; derive 5x5 output of 5x5 tiles.
# Header template masks for each source color, in group order.
colors=[8,2,7,4]
labels=[3,4,1,6]
header={}
for col,color in zip([0,6,12,18],colors):
    header[color]=[[1 if G[r][col+c]==color else 0 for c in range(5)] for r in range(5)]
header, {k:v for k,v in header.items()}

mapping=dict(zip(colors,labels))
out=[[0]*25 for _ in range(25)]
occupants={}
for rr in range(5):
 for cc in range(5):
  found=[]
  for base in [0,6,12,18]:
   # nonzero source marker, excluding any blank cells
   val=G[6+rr][base+cc]
   if val not in (0,5): found.append(val)
  if len(found)>1: print('overlap',rr,cc,found)
  if found:
   src=found[0]; dst=mapping[src]; mask=header[src]
   occupants[(rr,cc)]=(src,dst)
   for i in range(5):
    for j in range(5):
     if mask[i][j]: out[rr*5+i][cc*5+j]=dst
print('occupants',occupants)
print('\n'.join(' '.join(map(str,row)) for row in out))
